INSERT INTO `products` VALUES (1,1,1,'MacBook Pro 14','M3-2024',219990.00,'16 ГБ','14.2\"','Серый космос','Профессиональный ноутбук с чипом Apple M3 Pro, Liquid Retina XDR дисплеем и 18 часами автономной работы.',5,,'image/jpeg','2025-01-06 10:00:00'),(2,1,5,'ROG Strix G15','G513RC',124990.00,'16 ГБ','15.6\"','Чёрный','Игровой ноутбук с процессором AMD Ryzen 7 и видеокартой RTX 3050. Идеален для современных игр.',8,,'image/jpeg','2025-01-07 10:00:00'),(3,1,9,'ThinkPad X1 Carbon','Gen 11',159990.00,'32 ГБ','14\"','Чёрный','Бизнес-ноутбук премиум-класса с весом всего 1.12 кг и сертификацией военного стандарта.',4,,'image/jpeg','2025-01-08 10:00:00'),(4,1,7,'Pavilion 15','15-eg2055ci',74990.00,'16 ГБ','15.6\"','Серебристый','Универсальный ноутбук для дома и учёбы с Intel Core i5 и SSD на 512 ГБ.',12,,'image/jpeg','2025-01-09 10:00:00'),(5,1,8,'XPS 13','9340',169990.00,'16 ГБ','13.4\"','Платиновый','Ультрабук с InfinityEdge дисплеем, Intel Core Ultra 7 и поддержкой Wi-Fi 7.',6,,'image/jpeg','2025-01-10 10:00:00'),(6,2,1,'iPhone 15 Pro','A2848',119990.00,'256 ГБ','6.1\"','Титан натуральный','Флагман Apple с чипом A17 Pro, титановым корпусом и системой камер Pro.',15,,'image/jpeg','2025-01-11 10:00:00'),(7,2,2,'Galaxy S24 Ultra','SM-S928B',134990.00,'512 ГБ','6.8\"','Титановый чёрный','Топовый смартфон Samsung со стилусом S Pen и камерой 200 МП.',10,,'image/jpeg','2025-01-12 10:00:00'),(8,2,10,'14 Pro','23116PN5BR',89990.00,'512 ГБ','6.73\"','Чёрный','Флагман Xiaomi с оптикой Leica и процессором Snapdragon 8 Gen 3.',9,,'image/jpeg','2025-01-13 10:00:00'),(9,2,14,'Pixel 8','GZPF0',64990.00,'128 ГБ','6.2\"','Обсидиан','Смартфон Google с чипом Tensor G3 и продвинутыми ИИ-возможностями съёмки.',11,,'image/jpeg','2025-01-14 10:00:00'),(10,2,12,'Magic 6 Pro','BVL-N49',84990.00,'256 ГБ','6.78\"','Чёрный','Премиум-смартфон Honor с тройной камерой и большим аккумулятором 5600 мАч.',7,,'image/jpeg','2025-01-15 10:00:00'),(11,3,1,'iPad Air 11','M2-2024',74990.00,'128 ГБ','11\"','Звёздный свет','Планшет с чипом Apple M2, поддержкой Apple Pencil Pro и Liquid Retina дисплеем.',9,,'image/jpeg','2025-01-16 10:00:00'),(12,3,2,'Galaxy Tab S9','SM-X710',79990.00,'256 ГБ','11\"','Графит','Планшет Samsung с AMOLED экраном и стилусом S Pen в комплекте.',6,,'image/jpeg','2025-01-17 10:00:00'),(13,3,10,'Pad 6','23043RP34G',32990.00,'128 ГБ','11\"','Серый','Бюджетный планшет с экраном 144 Гц и поддержкой стилуса Smart Pen.',14,,'image/jpeg','2025-01-18 10:00:00'),(14,4,1,'AirPods Pro 2','USB-C',24990.00,'—','—','Белый','Беспроводные наушники с активным шумоподавлением второго поколения и зарядным кейсом MagSafe.',25,,'image/jpeg','2025-01-19 10:00:00'),(15,4,3,'WH-1000XM5','WH1000XM5/B',34990.00,'—','—','Чёрный','Топовые накладные наушники с лучшим в классе шумоподавлением и 30 часами работы.',8,,'image/jpeg','2025-01-20 10:00:00'),(16,4,15,'Tune 770NC','JBLT770NCBLK',8990.00,'—','—','Чёрный','Полноразмерные наушники с шумоподавлением и 70 часами автономной работы.',18,,'image/jpeg','2025-01-21 10:00:00'),(17,5,15,'Charge 5','JBLCHARGE5BLK',14990.00,'—','—','Чёрный','Портативная Bluetooth-колонка с защитой IP67 и автономностью 20 часов.',17,,'image/jpeg','2025-01-22 10:00:00'),(18,5,16,'SoundLink Flex','SLF',18990.00,'—','—','Синий','Компактная колонка Bose с фирменным звуком PositionIQ и водозащитой IP67.',9,,'image/jpeg','2025-01-23 10:00:00'),(19,6,1,'Watch Series 9','GPS 45mm',39990.00,'32 ГБ','1.9\"','Полночный','Умные часы Apple с чипом S9, ярким дисплеем 2000 нит и функцией Double Tap.',13,,'image/jpeg','2025-01-24 10:00:00');
INSERT INTO `products` VALUES (20,6,2,'Galaxy Watch 6','SM-R940',24990.00,'16 ГБ','1.5\"','Графит','Часы Samsung с AMOLED-дисплеем, мониторингом сна и измерением давления.',10,,'image/jpeg','2025-01-25 10:00:00'),(21,7,4,'OLED55C3','OLED55C3RLA',124990.00,'—','55\"','Чёрный','OLED-телевизор LG с процессором α9 Gen6 AI и поддержкой Dolby Vision IQ.',4,,'image/jpeg','2025-01-26 10:00:00'),(22,7,2,'Neo QLED QN85C','QE65QN85CAU',159990.00,'—','65\"','Серебристый','QLED-телевизор Samsung с Mini LED подсветкой и частотой 120 Гц.',3,,'image/jpeg','2025-01-27 10:00:00'),(23,8,4,'UltraGear 27GP850','27GP850-B',39990.00,'—','27\"','Чёрный','Игровой монитор LG с матрицей Nano IPS, 165 Гц и временем отклика 1 мс.',7,,'image/jpeg','2025-01-28 10:00:00'),(24,8,5,'TUF Gaming VG27AQ','VG27AQ',31990.00,'—','27\"','Чёрный','Монитор Asus TUF с разрешением QHD, 165 Гц и технологией G-Sync.',8,,'image/jpeg','2025-01-29 10:00:00'),(25,9,3,'PlayStation 5 Slim','CFI-2000',64990.00,'1 ТБ','—','Белый','Игровая консоль Sony нового поколения с поддержкой 4K и трассировкой лучей.',6,,'image/jpeg','2025-01-30 10:00:00'),(26,9,13,'Xbox Series X','RRT-00010',59990.00,'1 ТБ','—','Чёрный','Самая мощная консоль Xbox с поддержкой 8K и Quick Resume.',5,,'image/jpeg','2025-01-31 10:00:00'),(27,10,3,'Alpha A7 IV','ILCE-7M4',249990.00,'—','—','Чёрный','Полнокадровая беззеркальная камера Sony с матрицей 33 МП и видео 4K/60p.',3,,'image/jpeg','2025-02-01 10:00:00'),(28,14,3,'DualSense Edge','CFI-ZCP1W',21990.00,'—','—','Белый','Премиальный геймпад для PS5 с настраиваемыми элементами управления.',11,,'image/jpeg','2025-02-02 10:00:00');
