INSERT INTO `reviews` VALUES (1,1,1,5,'Отличный товар, всё пришло вовремя. Качество на высоте, рекомендую к покупке!','2025-04-11 11:00:00'),(2,2,2,4,'Покупкой доволен. Соответствует описанию, упаковка хорошая.','2025-04-12 13:00:00'),(3,3,3,4,'Брал в подарок, всё понравилось. Спасибо магазину за быструю доставку.','2025-04-13 15:00:00'),(4,4,4,5,'Не понравилось качество упаковки, но сам товар отличный.','2025-04-14 17:00:00'),(5,5,5,4,'Пользуюсь уже месяц, никаких нареканий нет. Советую всем.','2025-04-15 19:00:00'),(6,6,6,3,'Цена/качество — топ. Лучше, чем я ожидал.','2025-04-16 21:00:00'),(7,7,7,4,'Слегка дольше доставлялся, но сам товар оригинальный, работает идеально.','2025-04-17 23:00:00'),(8,8,8,3,'Хорошая модель за свои деньги. Менеджер магазина был очень вежлив.','2025-04-19 01:00:00'),(9,9,9,3,'Соответствует характеристикам, никаких подделок. Магазин надёжный.','2025-04-20 03:00:00'),(10,10,10,5,'Брал на замену старому, обновление чувствуется сразу.','2025-04-21 05:00:00'),(11,11,11,5,'Доволен покупкой, привезли быстро, всё работает.','2025-04-22 07:00:00'),(12,12,12,5,'Качество хорошее, но я ожидал большего за такую цену.','2025-04-23 09:00:00'),(13,13,13,4,'Идеально для повседневного использования.','2025-04-24 11:00:00'),(14,14,14,5,'Радует автономность и дизайн. Однозначно стоит своих денег.','2025-04-25 13:00:00'),(15,15,15,5,'Хорошее устройство, всё работает как часы.','2025-04-26 15:00:00'),(16,1,16,4,'Заказывал второй раз, опять всё на высшем уровне.','2025-04-27 17:00:00'),(17,2,17,5,'Прекрасный гаджет, рад покупке.','2025-04-28 19:00:00'),(18,3,18,4,'Соотношение цены и характеристик отличное.','2025-04-29 21:00:00');
